$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$source = (Get-ChildItem 'C:\Users\BlacK\Downloads' -Filter '*.png' | Select-Object -First 1).FullName
$output = Join-Path $PSScriptRoot '..\docs\questionnaire_analytics_feature_intro.pptx'
if ([string]::IsNullOrWhiteSpace($source)) { throw 'PNG source image was not found.' }
$tmp = Join-Path $env:TEMP ('pptx_' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tmp -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $tmp 'ppt\slides\_rels') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $tmp 'ppt\media') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $tmp 'ppt\_rels') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $tmp '_rels') -Force | Out-Null

function Put([string]$relative, [string]$content) {
  $path = Join-Path $tmp $relative
  $dir = Split-Path $path -Parent
  if (!(Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [IO.File]::WriteAllText($path, $content, [Text.UTF8Encoding]::new($false))
}

Copy-Item $source (Join-Path $tmp 'ppt\media\image.png')

Put '[Content_Types].xml' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/><Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/><Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/><Override PartName="/ppt/slides/slide1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/><Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/></Types>'
